fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // We assume `a.len() == b.len()`. For each pair of elements,
    // record `true` if they differ, otherwise `false`.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x != y)
     .collect()
}

fn main() {
    let a = vec![1, -5, 0, 127];
    let b = vec![1,  5, 0,  -127];
    let result = not_equal(a, b);
    assert_eq!(result, vec![false, true, false, true]);
    println!("All tests passed!");
}